content.solution_code:
class Weapon {
    constructor(weaponName, baseDamage) {
        this.weaponName = weaponName;
        this.baseDamage = baseDamage;
    }

    getAttackMessage() {
        return `${this.weaponName} hits for ${this.baseDamage} damage.`;
    }
}

class Sword extends Weapon {
    constructor(swordName, baseDamage, edgeSharpness) {
        super(swordName, baseDamage);
        this.edgeSharpness = edgeSharpness;
    }

    getAttackMessage() {
        const totalDamage = this.baseDamage + this.edgeSharpness;
        return `${this.weaponName} (Sword) slices for ${totalDamage} damage!`;
    }

    sharpenBlade() {
        this.edgeSharpness += 10;
        return `${this.weaponName} has been sharpened! Edge sharpness is now ${this.edgeSharpness}.`;
    }
}

